export function createSchemaModifier<T extends Record<string, Table>>(
  schema: T,
): SchemaModifier<Schemas<T>> {
  return new InternalSchemaModifier(schema) as unknown as SchemaModifier<
    Schemas<T>
  >;
}

class InternalSchemaModifier<T extends Record<string, Table>> {
  private readonly modifications: Partial<
    Record<string, (baseSchemas: SchemaGroup) => Partial<SchemaGroup>>
  > = {};

  constructor(private readonly schema: T) {}

  modify(
    key: string,
    factory: (baseSchemas: SchemaGroup) => Partial<SchemaGroup>,
  ) {
    this.modifications[key] = factory;
    return this;
  }

  create() {
    const modifiedSchema: Record<string, SchemaGroup> = {};
    for (const key in this.schema) {
      const table = this.schema[key];
      if (!table) continue;
      const tableName = getTableName(table);

      const baseSchemaGroup = {
        insert: createInsertSchema(table),
        select: createSelectSchema(table),
        update: createUpdateSchema(table),
      };
      const modifiedSchemaGroup =
        tableName in this.modifications ?
          this.modifications[tableName]?.(baseSchemaGroup)
        : undefined;
      modifiedSchema[tableName] = { ...baseSchemaGroup, ...modifiedSchemaGroup };
    }
    return modifiedSchema;
  }

  private static selectWithRelation(
    modifiedSchema: Record<string, SchemaGroup>,
    relations: Record<string, Record<string, Relation<string>>>,
    currentEntry: string,
    selectedRelations: Record<string, unknown>,
  ): z.ZodObject {
    if (!(currentEntry in modifiedSchema) || !modifiedSchema[currentEntry])
      throw new Error("Invalid key");
    const currentSelectSchema = modifiedSchema[currentEntry].select;
    let selectWithRelationSchema = currentSelectSchema;
    for (const key in selectedRelations) {
      if (!selectedRelations[key]) continue;
      const currentRelation = relations[currentEntry]?.[key];
      if (!currentRelation) throw new Error("Invalid relation");
      if (!isTable(currentRelation.targetTable)) throw new Error("Relation target is not a table");
      const target = getTableName(currentRelation.targetTable);
      if (!modifiedSchema[target]) throw new Error("Relation target not found in source schema");

      const innerSchema =
        typeof selectedRelations[key] === "object" ?
          InternalSchemaModifier.selectWithRelation(
            modifiedSchema,
            relations,
            target,
            selectedRelations[key] as Record<string, unknown>,
          )
        : modifiedSchema[target].select;

      const inner =
        currentRelation.relationType === "one" ?
          (<One<string>>currentRelation).optional ?
            z.optional(innerSchema)
          : innerSchema
        : z.array(innerSchema);

      selectWithRelationSchema = selectWithRelationSchema.extend({
        [key]: inner,
      });
    }
    return selectWithRelationSchema;
  }

  withRelations(
    relations: ExtractTablesWithRelationsParts<AnyRelationsBuilderConfig, T>,
  ) {
    const modifiedSchema = this.create();
    const schemaWithRelationsExtension: Record<
      string,
      SchemaGroup & {
        selectWithRelations?: (
          relations: Record<string, unknown>,
        ) => z._ZodType;
      }
    > = { ...modifiedSchema };
    const relationsByTableName: Record<
      string,
      Record<string, Relation<string>>
    > = {};
    for (const key in relations) {
      const relation = relations[key];
      if (!relation) continue;
      const tableName = getTableName(relation.table);
      if (!tableName) continue;
      relationsByTableName[tableName] =
        relation.relations;
    }

    for (const key in relationsByTableName) {
      if (!schemaWithRelationsExtension[key]) continue;
      schemaWithRelationsExtension[key].selectWithRelations = (
        selectedRelations,
      ) =>
        InternalSchemaModifier.selectWithRelation(
          modifiedSchema,
          relationsByTableName,
          key,
          selectedRelations,
        );
    }
    return { create: () => schemaWithRelationsExtension };
  }
}

type KeyValuePairs<T extends object> =
  keyof T extends infer A ?
    A extends keyof T ?
      [A, T[A]]
    : never
  : never;

export const getEntries = Object.entries as <T extends object>(
  it: T,
) => KeyValuePairs<T>[];

export const getKeys = Object.keys as <T extends object>(it: T) => (keyof T)[];

type MergeResult<T1 extends object, T2 extends object, R> = Record<
  keyof T1 | keyof T2,
  T1[keyof T1] | T2[keyof T2] | R
>;
type MergeStrategy<T1 extends object, T2 extends object, R> = (
  val1: T1[keyof T1],
  val2: T2[keyof T2],
) => R;
export const merge = <T1 extends object, T2 extends object, R>(
  a: T1,
  b: T2,
  strategy: MergeStrategy<NoInfer<T1>, NoInfer<T2>, R>,
): MergeResult<T1, T2, R> => {
  const merged = {} as MergeResult<T1, T2, R>;
  const keys = new Set<keyof T1 | keyof T2>();
  const isKeyInBoth = (key: keyof T1 | keyof T2): key is keyof T1 & keyof T2 =>
    key in a && key in b;
  const isKeyIn = <T extends T1 | T2>(
    key: keyof T1 | keyof T2,
    it: T,
  ): key is (keyof T1 | keyof T2) & keyof T => key in it;
  getKeys(a).forEach((key) => keys.add(key));
  getKeys(b).forEach((key) => keys.add(key));
  for (const key of keys) {
    if (isKeyInBoth(key)) merged[key] = strategy(a[key], b[key]);
    else if (isKeyIn(key, a)) merged[key] = a[key];
    else if (isKeyIn(key, b)) merged[key] = b[key];
  }
  return merged;
};
export const mergeStrategies = {
  concat:
    <T1 extends object, T2 extends object>(): MergeStrategy<
      T1,
      T2,
      [T1[keyof T1], T2[keyof T2]]
    > =>
    (v1, v2) => [v1, v2],
  concatFlat:
    <
      T1 extends Record<string | number | symbol, unknown[]>,
      T2 extends Record<string | number | symbol, unknown[]>,
    >(): MergeStrategy<T1, T2, [...T1[keyof T1], ...T2[keyof T2]]> =>
    (v1, v2) => [...v1, ...v2],
};
